import { DatepickerOptions } from './Default';
type HotKeyAction = (dateParts: {
    month: number;
    year: number;
    date: number;
}, dp: any) => void;
type KeyCombination = string[];
type HotKeyMapKey = KeyCombination | KeyCombination[];
export default class DatepickerKeyboard {
    dp: any;
    opts: DatepickerOptions;
    pressedKeys: Set<string>;
    hotKeys: Map<HotKeyMapKey, HotKeyAction>;
    constructor({ dp, opts }: {
        dp: any;
        opts: DatepickerOptions;
    });
    init(): void;
    bindKeyboardEvents(): void;
    destroy(): void;
    getInitialFocusDate(): Date;
    focusNextCell(keyName: string): void;
    registerKey(keyName: string): void;
    removeKey(keyName: string): void;
    handleHotKey: (combination: HotKeyMapKey) => void;
    isHotKeyPressed: () => HotKeyMapKey | false;
    isArrow: (keyCode: number) => boolean;
    onKeyDown: (e: KeyboardEvent) => void;
    onKeyUp: (e: KeyboardEvent) => void;
}
export {};
